// 전: 무엇이든 들어간다
function charge(amount: number, currency: string) {}
charge(-100, 'KRW');       // 음수 통과
charge('KRW', -100 as any); // 인자 뒤바뀜도 통과

// 후: 개념을 타입으로 (규칙을 생성자에 넣는다 — 3장)
class Money {
  private constructor(readonly amount: number, readonly currency: string) {}
  static of(amount: number, currency: string): Money {
    if (amount < 0) throw new Error('음수 금액');   // 잘못된 값은 생성 불가
    return new Money(amount, currency);
  }
}
function charge(m: Money) {}   // 타입이 계약

class Order {
  private status: 'placed' | 'shipped' | 'cancelled';
  cancel(now: Date) {
    if (this.status === 'shipped')
      throw new DomainError('배송 시작 후에는 취소할 수 없습니다');
    this.status = 'cancelled';
  }
}
// 화면·API·배치 어디서든 order.cancel() 만 부른다
// 규칙이 한곳에 있어 빠질 수 없다 — 항상 유효한 상태 유지
